test('v0.4.1 malformed recipe topology downgrades independently in real JSON import',async()=>{
 await page.goto('http://127.0.0.1:18787/selective-interactions.html');await page.locator('#table input').evaluate(e=>{e.value=30;e.dispatchEvent(new Event('input',{bubbles:true}));});await page.locator('#table button').click();await start('json');await page.locator('#fourier h2').click();await page.keyboard.press('ArrowUp');const pending=context.waitForEvent('page',p=>p.url().includes('/preview.html'));await page.keyboard.press('Enter');const captured=await pending;await expect(captured.locator('#save')).toBeEnabled();const original=JSON.parse(await fs.readFile(await save(captured,'v041-topology-input.json'),'utf8'));await captured.close();
 const get=(s,p)=>p.split('.').slice(1).reduce((n,i)=>n.children[Number(i)],s.tree);
 const node=(tag,ns='html')=>({tag,ns,attrs:{},style:{},children:[]});
 const invalid=structuredClone(original);invalid.tree={...node('input'),attrs:{type:'range',disabled:''},children:[invalid.tree]};for(const b of invalid.behaviors)for(const k of Object.keys(b.bindings))b.bindings[k]=b.bindings[k].replace(/^0/,'0.0');const rejected=await context.newPage();await rejected.goto(`chrome-extension://${extensionId}/import.html`);await rejected.locator('#file').setInputFiles({name:'void.json',mimeType:'application/json',buffer:Buffer.from(JSON.stringify(invalid))});await expect(rejected.locator('#status')).toContainText('空元素');await rejected.close();
 const foreign=structuredClone(original);foreign.behaviors=[];foreign.tree={...node('svg','svg'),children:[{...node('details'),children:[{...node('summary'),children:[{text:'Fold'}]}]}]};const foreignImport=await importFile('foreign-details.json',JSON.stringify(foreign));await foreignImport.preview.locator('#strategy').selectOption('interactive');await expect(foreignImport.preview.locator('#save')).toBeDisabled();await expect(foreignImport.preview.locator('#message')).toContainText('没有可恢复交互');await expect(foreignImport.preview.locator('#interactionReport')).toContainText('static-fallback');await foreignImport.preview.close();await foreignImport.importer.close();
 const cases=[
  ['detached-body',s=>{const b=s.behaviors[1],root=get(s,b.bindings.root),table=get(s,b.bindings.body.split('.').slice(0,-1).join('.')),body=get(s,b.bindings.body);table.children.splice(table.children.indexOf(body),1);b.bindings.body=b.bindings.root+'.'+root.children.length;root.children.push(body);}],
  ['nested-table',s=>{const b=s.behaviors[1],parts=b.bindings.body.split('.'),table=get(s,parts.slice(0,-1).join('.'));table.children.unshift(node('table'));parts[parts.length-1]=String(Number(parts.at(-1))+1);b.bindings.body=parts.join('.');}],
  ['svg-breakout',s=>{const b=s.behaviors[0],parts=b.bindings.curve.split('.'),svg=get(s,parts.slice(0,-1).join('.'));svg.children.unshift(node('div'));parts[parts.length-1]=String(Number(parts.at(-1))+1);b.bindings.curve=parts.join('.');}],
  ['output-ancestor',s=>{const b=s.behaviors[0],root=get(s,b.bindings.root),out=get(s,b.bindings.output),old=b.bindings.output;out.children=root.children.filter(n=>n!==out);root.children=[out];for(const [key,p] of Object.entries(b.bindings)){if(key==='root')continue;if(key==='output'){b.bindings[key]=b.bindings.root+'.0';continue;}let i=Number(p.slice(b.bindings.root.length+1).split('.')[0]);if(i>Number(old.split('.').at(-1)))i--;const rest=p.slice(b.bindings.root.length+1).split('.').slice(1);b.bindings[key]=[b.bindings.root,'0',i,...rest].join('.');}}]
 ];
 for(const [name,change] of cases){const s=structuredClone(original);change(s);const imported=await importFile(name+'.json',JSON.stringify(s));await expect(imported.preview.locator('#report')).toContainText('结构不匹配');await imported.preview.locator('#format').selectOption('json');await expect(imported.preview.locator('#save')).toBeEnabled();const normalized=JSON.parse(await fs.readFile(await save(imported.preview,'v041-'+name+'.json'),'utf8'));expect(normalized.behaviors).toHaveLength(1);expect(normalized.behaviors[0].recipe).toBe(name.includes('body')||name==='nested-table'?'fourier@1':'table@1');await imported.preview.locator('#format').selectOption('html');await expect(imported.preview.locator('#save')).toBeEnabled();const file=await save(imported.preview,'v041-'+name+'.html'),opened=await context.newPage(),errors=[];opened.on('pageerror',e=>errors.push(e.message));await opened.goto('file://'+file);if(normalized.behaviors[0].recipe==='fourier@1'){await opened.locator('input').first().evaluate(e=>{e.value=5;e.dispatchEvent(new Event('input',{bubbles:true}));});await expect(opened.locator('output').first()).toContainText('N=5');}else{await opened.getByRole('button',{name:'切换升降序'}).click();await expect(opened.locator('tbody tr:not([hidden])')).toHaveText(['丙40','丁45']);}expect(errors).toEqual([]);if(name==='nested-table')await imported.preview.screenshot({path:path.join(evidence,'v041-topology-downgrade.png'),fullPage:true});await opened.close();await imported.preview.close();await imported.importer.close();}
});
